// import { Card, CardContent } from "@/components/ui/card";
import React from "react";

export default function Frame() {
  // Data for the hexagon features
  const features = [
    {
      id: 1,
      text: "Toy-based\nlearning",
      position: "top-4 left-[23px]",
    },
    {
      id: 2,
      text: "Real-time\nlearning\nanalytics",
      position: "top-[93px] left-[13px]",
    },
    {
      id: 3,
      text: "Learning in the native\nlanguage",
      position: "top-[110px] left-20",
    },
    {
      id: 4,
      text: "Report generation",
      position: "top-[113px] left-[150px]",
    },
    {
      id: 5,
      text: "Dynamic\nusage report\ngeneration",
      position: "top-14 left-[122px]",
      fontSize: "text-[7px]",
    },
    {
      id: 6,
      text: "1000+\ninteractive\nspeaking\ncharts",
      position: "top-12 left-[189px]",
    },
    {
      id: 7,
      text: "Visual and\nauditory\nfeedback",
      position: "top-[116px] left-[226px]",
    },
    {
      id: 8,
      text: "Projector\nconnectivity",
      position: "top-[23px] left-[255px]",
      fontSize: "text-[7px]",
    },
  ];

  // Data for the connecting lines
  const lines = [
    { position: "top-[52px] left-[238px] w-[22px] h-[13px]" },
    { position: "top-[122px] left-[68px] w-[11px] h-px" },
    { position: "top-[132px] left-[202px] w-5 h-px" },
    { position: "top-[93px] left-[119px] w-[17px] h-5" },
    { position: "top-[102px] left-[225px] w-[9px] h-3" },
    { position: "top-[76px] left-[42px] w-[9px] h-3.5" },
    { position: "top-[94px] left-[152px] w-[9px] h-[23px]" },
  ];

  // Data for the hexagon positions
  const hexagons = [
    { position: "top-[101px] left-[222px]" },
    { position: "top-[89px] left-[15px]" },
    { position: "top-2 left-[254px]" },
    { position: "top-24 left-[78px]" },
    { position: "top-[42px] left-[116px]" },
    { position: "top-[13px] left-[23px]" },
    { position: "top-[47px] left-[186px]" },
    { position: "top-[102px] left-[148px]" },
  ];

  return (
    <div className="bg-transparent flex flex-row justify-center w-full">
      <Card className="w-[416px] h-[180px] bg-[#f4fcff] rounded-[10px] border-none">
        <CardContent className="relative h-[180px] p-0">
          {/* Title */}
          <div className="absolute w-[139px] h-[25px] top-1 left-[98px] rotate-[0.44deg] font-extrabold text-[10px] text-center tracking-[0] leading-normal">
            <span className="text-[#2e3192]">WHY CHOOSE</span>
            <span className="text-[#df4444]"> SHIKSHA?</span>
          </div>

          {/* Robot image */}
          <div className="absolute w-[141px] h-[141px] top-[39px] left-[275px]">
            <img
              className="w-full h-full object-cover"
              alt="Shiksha Robot"
              src=""
            />
          </div>

          {/* Hexagon shapes with connecting lines */}
          {hexagons.map((hexagon, index) => (
            <div
              key={`hexagon-${index}`}
              className={`h-[63px] absolute w-[55px] ${hexagon.position}`}
            >
              <div className="w-full h-full bg-blue-500 clip-hexagon"></div>
            </div>
          ))}

          {/* Feature text */}
          {features.map((feature) => (
            <div
              key={`feature-${feature.id}`}
              className={`absolute w-[60px] h-[52px] ${
                feature.position
              } font-bold ${
                feature.fontSize || "text-[8px]"
              } text-white text-center tracking-[0] leading-normal whitespace-pre-line`}
            >
              {feature.text}
            </div>
          ))}

          {/* Connecting lines */}
          {lines.map((line, index) => (
            <div
              key={`line-${index}`}
              className={`absolute bg-red-500 ${line.position}`}
            ></div>
          ))}
        </CardContent>
      </Card>
    </div>
  );
}
